# Let me check: input and output both have 12 8s.
# So it's a geometric transform without value deletion.

# Let me visualize the positions of 8s
in_8s = [(2,5), (3,3), (3,4), (3,5), (3,7), (4,3), (5,3), (5,4), (5,5), (5,6), (6,2), (6,6)]
out_8s = [(2,5), (3,2), (3,3), (4,3), (4,5), (4,6), (5,3), (5,5), (6,3), (6,4), (6,5), (7,2)]

print("Input 8s (9x10 frame):", in_8s)
print("Output 8s (10x9):", out_8s)

# Let me try to find a mapping
# If I rotate 90° CW: (r, c) -> (c, 8-r)
print("\nTesting 90° CW rotation: (r,c) -> (c, 8-r)")
rotated_in = []
for r, c in in_8s:
    new_r, new_c = c, 8 - r
    rotated_in.append((new_r, new_c))
print("Expected if only rotate: ", rotated_in)

# Test 180: (r, c) -> (8-r, 9-c)
print("\nTesting 180° rotation: (r,c) -> (8-r, 9-c)")
rotated180 = []
for r, c in in_8s:
    new_r, new_c = 8-r, 9-c
    rotated180.append((new_r, new_c))
print("Expected if only rotate 180: ", rotated180)

# Test 270 CCW: (r, c) -> (9-c, r)
print("\nTesting 270° CCW: (r,c) -> (9-c, r)")
rotated270 = []
for r, c in in_8s:
    new_r, new_c = 9-c, r
    rotated270.append((new_r, new_c))
print("Expected if rotate 270: ", rotated270)

