# Try all combos
def flip_h(p):
    r, c = p
    return (r, 8-c)

def flip_v(p):
    r, c = p
    return (8-r, c)

def rotate_90_cw(p):
    r, c = p
    return (c, 8-r)

def rotate_180(p):
    r, c = p
    return (8-r, 9-c)

def rotate_270_ccw(p):
    r, c = p
    return (9-c, r)

# Actually, for rotation, need to handle both (r,c) and output dimensions
# Input points are 9x10, need to map to 10x9

# Let me be more careful
print("\n--- With proper dimension handling ---")

# after 90° CW rotate: input 9x10 -> output 10x9
# (r,c) in 9x10 maps to (new_r, new_c) in 10x9 where:
# new_r = c, new_c = 8-r
def transform_90cw(p):
    r, c = p
    return (c, 8-r)

def transform_180(p):
    # rotate 90cw twice
    r1, c1 = p
    r2, c2 = c1, 8-r1
    return (8-c2, r2)

def transform_270_ccw(p):
    r, c = p
    return (9-c, r)

def flip_h_adjusted(p):
    # h is 10 wide, so flip means c -> 9-c for output
    r, c = p
    return (r, 9-c)

def flip_v_adjusted(p):
    # v is 10 high, so flip means r -> 9-r
    r, c = p
    return (9-r, c)

# Now try combinations
from itertools import product

results = {}
for r_trans in ['identity', '90cw', '180', '270ccw']:
    for fh in [False, True]:
        for fv in [False, True]:
            def make_transform(base, fh, fv):
                def transform(p):
                    p = base(p)
                    if fv:
                        p = flip_v_adjusted(p)
                    if fh:
                        p = flip_h_adjusted(p)
                    return p
                return transform

            base_funcs = {
                'identity': lambda p: p,
                '90cw': transform_90cw,
                '180': transform_180,
                '270ccw': transform_270_ccw,
            }

            trans = make_transform(base_funcs[r_trans], fh, fv)
            mapped = trans(in_8s)
            matches = sum(1 for p in mapped if p in out_8s)
            key = (r_trans, fh, fv)
            results[key] = (matches, mapped)

# Sort by matches
sorted_results = sorted(results.items(), key=lambda x: x[1][0], reverse=True)
for key, (matches, mapped) in sorted_results:
    print(f"{key}: {matches}/12 match")
    if matches == 12:
